\label{def:POG_curves}
A reduced curve ${\mathcal{C}}$ in $\mathbb{P}^{2}_{\mathbb{C}}$ is called \textbf{plus-one generated} with the exponents $(d_1,d_2), d_1 \leq d_2$, and level $d_{3}$ if $D_0({\mathcal{C}})$ admits a minimal resolution of the form:
$$0 \rightarrow  S(-d_3-1) \rightarrow  S(-d_3) \oplus S(-d_2) \oplus S(-d_1) \rightarrow D_0({\mathcal{C}}) \rightarrow 0$$

\begin{enumerate}
\item A $3$-syzygy reduced curve ${\mathcal{C}}$ in $\mathbb{P}^{2}_{\mathbb{C}}$ of degree $d$ and exponents $(d_1,d_2,d_3)$ such that $d_{1}+d_{2}=d$ is precisely a plus-one generated curve with exponents $(d_{1}, d_{2})$ and level $d_{3}$. 
\item If ${\mathcal{C}}$ is a plus-one generated curve with $d_{2}=d_{3}$, then ${\mathcal{C}}$ is called \textbf{nearly-free}.
\end{enumerate}

\label{dimspl}
Let ${\mathcal{C}} : f=0$ be a reduced $3$-syzygy curve of degree $d\geq 3$ with the exponents $(d_{1},d_{2},d_{3})$. Then ${\mathcal{C}}$ is plus-one generated if and only if
$$\tau({\mathcal{C}}) = (d-1)^{2} - d_{1}(d-d_{1}-1) - (d_{3}-d_{2}+1).$$

\cite[Theorem 1.11]{A0}
\label{thm:Abe}
 Let ${\pazocal{A}}$ be a free arrangement of lines in  $\mathbb{P}^{2}_{\mathbb{C}}$. Then:
 \begin{enumerate}
     \item For $L \in {\pazocal{A}}$, the subarrangement ${\pazocal{A}} \setminus \{L\}$ is either free or plus-one generated.
     \item Let $L$ be a line in $\mathbb{P}^{2}_{\mathbb{C}}$. Then the arrangement ${\pazocal{A}} \cup \{L\}$ is either free or plus-one generated.
 \end{enumerate}

\label{XR}
Let us consider the conic-line arrangement $\mathcal{XR}\subset \mathbb{P}^{2}_{\mathbb{C}}$ given by the following defining polynomial:
\begin{multline*}
    Q(x,y,z)= (x^{2} + 2xy + y^{2} - xz)(x^2 + xy + 2yz - z^2 )(x^2 + xz + yz)(x^2 + xy + z^2 ) \\ (x^2 + 2xy - xz + yz)(x^2 - y^2 + xz + 2yz)y(x + z)(x + y - z)(x + y + z)(x - z)\bigg(x + \frac{1}{2}y\bigg).
\end{multline*}
This arrangement has $9$ ordinary sixfold and $12$ double intersection points. It is also worth noticing that all singularities are quasi-homogeneous. Using \verb}        } we can check that the arrangement $\mathcal{XR}$ is free with exponents $(d_{1},d_{2})=(4,13)$. Now we perform the addition technique. If we add to $\mathcal{XR}$ the line $\ell : x+2y+4z=0$, then the arrangement is plus-one generated with exponents $(d_{1},d_{2},d_{3})=(5,14,17)$. Looking more precisely, by adding the line $\ell$ we introduce $18$ additional double points to the resulting arrangement. 

However, using the same addition trick, we can obtain a free arrangement of conics and lines, and this can be achieved by adding to $\mathcal{XR}$, for instance, the line $\ell' : z=0$.

Using Proposition \ref{degreeb} and Proposition \ref{double} we see that $m \in \{4, ..., 12\}$. 
We start with a degree-wise characterization. For $m=4$ we have a plus-one generated arrangement described in Proposition \ref{double}, so we are going to present constructions of plus-one generated conic-line arrangements in degrees $m\in \{5,6,7,8\}$ with types of singularities prescribed above.
\begin{itemize}
\item[$(m=5)$] Let $\mathcal{CL}_{5}$ be defined by the following polynomial:
$$Q(x,y,z) = x(x+y)(x-y)(x^2 + y^2 - z^2).$$ Here we have $n_{3}=1$ and $n_{2}=6$, so $\tau(\mathcal{CL}_{5})=10$. Then we can check directly, using \verb}        }, that $(d_{1},d_{2},d_{3}) = (2,3,4)$, so $\mathcal{CL}_5$ is plus-one generated.
\item[$(m=6)$]  Let $\mathcal{CL}_{6}$ be defined by the following polynomial:
$$Q(x,y,z) = x(y-x)(y+x)(x^2 + y^2 - z^2)\bigg(y-\frac{\sqrt{2}}{2}z\bigg).$$ 
Here we have $n_{3}=3$ and $n_{2}=5$, so $\tau(\mathcal{CL}_{6})=17$. Then we can check directly, using \verb}        }, that $(d_{1},d_{2},d_{3}) = (3,3,4)$, so $\mathcal{CL}_6$ is plus-one generated.
\item[$(m=7)$]  Let $\mathcal{CL}_{7}$ be defined by the following polynomial:
$$Q(x,y,z) = x(y-x)(y+x)(x^2 + y^2 - z^2)\bigg(y-\frac{\sqrt{2}}{2}z\bigg)\bigg(y+\frac{\sqrt{2}}{2}z\bigg).$$ 
Here we have $n_{3}=5$ and $n_{2}=5$, so $\tau(\mathcal{CL}_{6})=25$. Then we can check directly, using \verb}        }, that $(d_{1},d_{2},d_{3}) = (3,4,5)$, so $\mathcal{CL}_7$ is plus-one generated.
\item[$(m=8)$] Let us consider the arrangement $\mathcal{CL}_{8}$ that is given by the following defining polynomial:
$$Q(x,y,z) = (x-y)(x+y)(x-z)(x+z)(y-z)(y+z)(x^{2} + y^{2} - z^{2}).$$ 
It is easy to see that we have $n_{2}=7$, $t_{2}=4$ and $n_{3}=4$, which gives us $\tau(\mathcal{CL}_{8}) = 35$. Using \verb}        } we can check that $(d_{1},d_{2},d_{3}) = (4,4,5)$, so $\mathcal{CL}_{8}$ is plus-one generated.
\end{itemize}
Now we are going to exclude the existence of arrangements with $m \in \{11,12\}.$
\begin{itemize}
\item[$(m=11)$] Using Proposition \ref{degreeb}, we see that
$$\frac{11}{2} \geq d_{1} \geq \frac{22}{3}-2,$$
and since $d_{1} \in \mathbb{Z}_{\geq 0}$, we arrive at a contradiction.
\item[$(m=12)$] We are going to use two important combinatorial constraints. First of all, we have the naive combinatorial count:
\begin{equation}
\label{clcount}
\binom{12}{2} - k = \binom{m}{2}-k = n_{2}+2t_{2}+3n_{3}.
\end{equation}
Next, we will use the following Hirzebruch-type inequality \cite[Proposition 4.4]{Gal}:
\begin{equation}
\label{hirpp}
8k +n_{2} + n_{3} \geq 8k+n_{2} + \frac{3}{4}n_{3} \geq d+ \frac{5}{2}t_{2}.
\end{equation}
By the assumption our arrangements are plus-one generated, so using Proposition \ref{degreeb} we see that
$$6 = \frac{m}{2} \geq d_{1} \geq \frac{2}{3}\cdot 12 - 2 = 6,$$
so we arrive at the case $d_{1}=d_{2}=6$ and $d_{3}>6$. By Proposition \ref{dimspl} we get
\begin{equation}
\label{dpw}
89 = d_{1}^{2}-d_{1}(m-1)+(m-1)^2 - \nu(\mathcal{CL}) = n_{2}+3t_{2}+4n_{3}.
\end{equation}
Combining \eqref{dpw} with the (naive) combinatorial count, we arrive at
\begin{equation}
t_{2}+n_{3}=23+k, \quad n_{2}+n_{3}=20-3k.
\end{equation}
From Hirzebruch-type inequality we get
\begin{equation}
5k+20 = 8k + n_{2} + n_{3} \geq d + \frac{5}{2}t_{2},
\end{equation}
so we have found the following upper-bound on the number of tacnodes:
$$t_{2} \leq \frac{2}{5}\bigg(5k+20\bigg) - \frac{2}{5}d = 2k+8-\frac{2}{5}d.$$
Using the above constraints, we have the following possibilities:
\begin{center}
\begin{tabular}{ |c|c|c|c|c| } 
$k$ & $d$ & $n_{3}\leq$ & $t_{2}\leq $ &$n_{3}+t_{2}\leq $ \\
 \hline \hline
 1 & 10 & 17 & 6  & 23 \\ 
 2 &  8 & 14 & 8  & 22 \\ 
 3 &  6 & 11 & 11 & 22 \\
 4 &  4 & 8  & 14 & 22 \\ 
 5 &  2 & 5  & 17 & 22 \\
 \hline
\end{tabular}\,\,.
\end{center}
Since $t_{2}+n_{3} = 23 + k \geq 24$, we arrive at a contradiction.
\end{itemize}

Let us  denote by $\alpha_L$ a homogeneous linear form that defines the line $L$. By \cite[Theorem 1.6, Remark 1.8]{STY}, we have the following exact sequence of vector bundles
\begin{equation}
\label{eq:triple_sheaves}
0 \rightarrow \mathcal{E}_{\mathcal{C}'}(-1) \overset{\alpha_L}\longrightarrow  \mathcal{E}_{\mathcal{C}} \rightarrow \mathcal{O}_L(1-|\mathcal{C}' \cap L|) \rightarrow 0
\end{equation}
where ${\mathcal{E}}_{\mathcal{C}}$ denotes the locally free sheaf (i.e. vector bundle) obtained by the sheafification of the graded module $D_0(\mathcal{C})$. We will compute $|\mathcal{C}' \cap L|$ via Chern numbers associated to the vector bundles in sequence \eqref{eq:triple_sheaves}. For a complex vector bundle $\mathcal{E}$, we denote by $c_i(\mathcal{E})$ is the $i$-th Chern number of $\mathcal{E}$.
The exact sequence \eqref{eq:triple_sheaves} implies the equality
\begin{equation}
\label{eq:chern2}
c_2(\mathcal{E}_{\mathcal{C}}) = c_2( \mathcal{E}_{\mathcal{C}'}(-1) ) + c_1( \mathcal{E}_{\mathcal{C}'}(-1) )c_1(\mathcal{O}_L(1-|\mathcal{C}' \cap L|)) + c_2(\mathcal{O}_L(1-|\mathcal{C}' \cap L|)),
\end{equation}
see for instance \cite[Section 3]{F} for details. 

If $\mathcal{C}$ is plus-one generated with exponents $(d_1, d_2)$ and level $d_3$, 
then we get, directly from Definition \ref{def:POG_curves}, formulas for the Chern numbers of the associated vector bundle $\mathcal{E}_{\mathcal{C}}$, in terms of the exponents and level. We will leave the details of this easy computation to the interested reader (check \cite{F} for the general theory and computations on Chern numbers). We have:
\begin{equation}
\label{eq:chern1_POG}
 c_1( \mathcal{E}_{\mathcal{C}}) = 1 - d_1 - d_2.
 \end{equation}
and 
\begin{equation}
\label{eq:chern2_POG}
c_2({\mathcal{E}}_{\mathcal{C}}) = d_1(d_2-1)+d_3-d_2+1.
\end{equation}

Since $\nu(\mathcal{C}') = \nu(\mathcal{C}) = 2$ in our hypothesis, we have $d'_3-d'_2 = d_3-d_2 = 1$.
Now we will substitute the formulas for Chern numbers \eqref{eq:chern1_POG} and \eqref{eq:chern2_POG} in the equality \eqref{eq:chern2}, taking into account also the formula for the Chern polynomial of $\mathcal{E}_{\mathcal{C}'}(-1) = \mathcal{E}_{\mathcal{C}'} \otimes _{\mathcal{O}_{\mathbb{P}^2}} \mathcal{O}_{\mathbb{P}^2}(-1)$ in terms of the Chern polynomial of $\mathcal{E}_{\mathcal{C}'}$, see again \cite[Section 3]{F}. We obtain the equality

$$c_2({\mathcal{E}}_{\mathcal{C}}) = (c_2({\mathcal{E}}_{\mathcal{C}'}) - c_1({\mathcal{E}}_{\mathcal{C}'})+ 1) + (-2+c_1({\mathcal{E}}_{\mathcal{C}'})) + c_2(\mathcal{O}_L(1-|\mathcal{C}' \cap L|)),$$
or explicitly
\begin{equation}
\label{eq:exponents}
d_1(d_2-1)+2 = \bigg(d'_1(d'_2-1)+2 - (1 - d'_1-d'_2) + 1 \bigg) + \bigg(-2+(1 - d'_1-d'_2)\bigg)+|\mathcal{C}' \cap L| .
\end{equation}
Observe that by \cite[Proposition 3.1]{DIS} we have $ d_1 \in \{d'_1, d'_1+1\}$. To complete our proof, let us first consider the case $d_1 = d'_1$. Then $d_2 = d'_2 +1$ and \eqref{eq:exponents} becomes 
$$|\mathcal{C}' \cap L| = d'_1+1.$$
Secondly, if  $d_1 = d'_1+1$, then $d_2 = d'_2 $, and  \eqref{eq:exponents} becomes 
$$|\mathcal{C}' \cap L| = d'_2.$$
In conclusion, we necessarily get $|\mathcal{C}' \cap L| \in \{d'_1+1, \; d'_2\}$, which completes the proof.

\label{ntt}
Let $C \subset \mathbb{P}^{2}_{\mathbb{C}}$ be a reduced curve of degree $m\geq 9$ admitting $n_{2}$ nodes, $t_{2}$ tacnodes, and $n_{3}$ ordinary triple points, then for a real number $\alpha \in [1/3, 2/3]$ one has
\begin{equation}
\label{ientt}
    (6\alpha -3\alpha^2)\cdot n_{2} + \bigg(-6\alpha^2 + 15\alpha - \frac{3}{8}\bigg)\cdot t_{2} + \bigg(-\frac{27}{4}\alpha^{2}+18\alpha\bigg)\cdot n_{3} \leq (3\alpha - \alpha^2)m^2 - 3\alpha m.
\end{equation}
